// Modern CashBack Page
const SimpleCashBackPage = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [activeTab, setActiveTab] = useState('featured');

  // Add scroll animation for elements
  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
        }
      });
    }, { threshold: 0.1 });
    
    document.querySelectorAll('.animateOnScroll').forEach(el => {
      observer.observe(el);
    });
    
    return () => {
      document.querySelectorAll('.animateOnScroll').forEach(el => {
        observer.unobserve(el);
      });
    };
  }, []);

  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
  };

  const handleSearch = (e) => {
    e.preventDefault();
    console.log(`Searching for: ${searchTerm}`);
  };

  return (
    <div className="pageContainer">
      {/* Modern Hero Section with Gradient Background */}
      <section className="heroSection">
        <div className="heroGradient"></div>
        <div className="heroContent">
          <div className="heroTextContent">
            <div className="heroTagline">SMART SHOPPING STARTS HERE</div>
            <h1 className="heroTitle">
              Earn <span className="heroTitleAccent">Cash Back</span> on Every Purchase
            </h1>
            <p className="heroSubtitle">
              Join over 500,000 smart shoppers who save money every time they shop online
            </p>
            
            <div className="heroCTA">
              <button className="primaryButton">
                Start Earning Now <FaArrowRight className="buttonIcon" />
              </button>
              <button className="secondaryButton">
                How It Works
              </button>
            </div>
            
            <div className="trustBadges">
              <div className="trustBadge">
                <FaStar className="trustIcon" />
                <span>4.8/5 Rating</span>
              </div>
              <div className="trustBadge">
                <FaBolt className="trustIcon" />
                <span>Fast Payouts</span>
              </div>
              <div className="trustBadge">
                <FaShieldAlt className="trustIcon" />
                <span>Secure & Private</span>
              </div>
            </div>
          </div>
          
          <div className="heroImageContainer">
            <div className="heroImageWrapper">
              <img src={productImage} alt="Cash back rewards" className="heroImage" />
              <div className="imageOverlay">
                <div className="overlayBadge">
                  <span className="badgeAmount">$1.2M+</span>
                  <span className="badgeText">Paid to Members</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
      
      {/* Enhanced Search Bar */}
      <section className="searchSection">
        <div className="searchContainer">
          <form onSubmit={handleSearch} className="searchForm">
            <div className="searchBar">
              <FaSearch className="searchIcon" />
              <input
                type="text"
                placeholder="Search for stores, brands, or products..."
                value={searchTerm}
                onChange={handleSearchChange}
                className="searchInput"
              />
              <button type="submit" className="searchButton">
                Search
              </button>
            </div>
          </form>
          
          <div className="quickLinks">
            <span className="quickLinksLabel">Popular:</span>
            {['Amazon', 'Walmart', 'Target', 'Nike', 'Apple'].map(store => (
              <button 
                key={store} 
                className="quickLinkButton"
                onClick={() => setSearchTerm(store)}
              >
                {store}
              </button>
            ))}
          </div>
        </div>
      </section>
      
      {/* Featured Content Tabs */}
      <section className="tabsSection">
        <div className="tabsContainer">
          <div className="tabsHeader">
            <button 
              className={`tabButton ${activeTab === 'featured' ? 'activeTab' : ''}`}
              onClick={() => setActiveTab('featured')}
            >
              Featured Deals
            </button>
            <button 
              className={`tabButton ${activeTab === 'trending' ? 'activeTab' : ''}`}
              onClick={() => setActiveTab('trending')}
            >
              Trending Stores
            </button>
            <button 
              className={`tabButton ${activeTab === 'categories' ? 'activeTab' : ''}`}
              onClick={() => setActiveTab('categories')}
            >
              Categories
            </button>
          </div>
          
          <div className="tabContent">
            {activeTab === 'featured' && (
              <div className="featuredDealsGrid">
                {fallbackOffers.map((offer) => (
                  <ModernCashBackCard key={offer.id} {...offer} />
                ))}
                <div className="viewMoreCard">
                  <div className="viewMoreContent">
                    <FaGift className="viewMoreIcon" />
                    <h3>More Deals Available</h3>
                    <p>Discover all our exclusive cash back offers</p>
                    <button className="viewMoreButton">
                      View All Deals <FaArrowRight />
                    </button>
                  </div>
                </div>
              </div>
            )}
            
            {activeTab === 'trending' && (
              <div className="storesGrid">
                {[
                  { id: 201, name: "Amazon", logo: productImage, cashbackRate: "Up to 5%", isPopular: true },
                  { id: 202, name: "Walmart", logo: productImage, cashbackRate: "3%", isPopular: true },
                  { id: 203, name: "Target", logo: productImage, cashbackRate: "2%", isPopular: false },
                  { id: 204, name: "Best Buy", logo: productImage, cashbackRate: "4%", isPopular: true },
                  { id: 205, name: "Nike", logo: productImage, cashbackRate: "8%", isPopular: false },
                  { id: 206, name: "Apple", logo: productImage, cashbackRate: "2%", isPopular: true },
                  { id: 207, name: "Samsung", logo: productImage, cashbackRate: "6%", isPopular: false },
                  { id: 208, name: "Adidas", logo: productImage, cashbackRate: "5%", isPopular: true }
                ].map((store) => (
                  <div key={store.id} className="storeCard">
                    <div className="storeLogoWrapper">
                      <img src={productImage} alt={store.name} className="storeLogo" />
                      {store.isPopular && <span className="popularBadge">Popular</span>}
                    </div>
                    <h3 className="storeName">{store.name}</h3>
                    <p className="storeCashback">{store.cashbackRate} Cash Back</p>
                    <button className="shopButton">Shop Now</button>
                  </div>
                ))}
              </div>
            )}
            
            {activeTab === 'categories' && (
              <div className="categoriesGrid">
                {[
                  { id: 1, name: "Electronics", icon: <FaRegLightbulb />, color: "#4299e1" },
                  { id: 2, name: "Fashion", icon: <FaShoppingBag />, color: "#ed64a6" },
                  { id: 3, name: "Home", icon: <FaGift />, color: "#48bb78" },
                  { id: 4, name: "Beauty", icon: <FaStar />, color: "#f6ad55" },
                  { id: 5, name: "Travel", icon: <FaRegClock />, color: "#667eea" },
                  { id: 6, name: "Food", icon: <FaPercentage />, color: "#f56565" }
                ].map(category => (
                  <div 
                    key={category.id} 
